import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"2.2 Process documents, tables, and web material","description":"Produce results with sources that can be checked and reused.","frontmatter":{"title":"2.2 Process documents, tables, and web material","description":"Produce results with sources that can be checked and reused.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-2/2-2.md","filePath":"en/delivery/stage-2/2-2.md","lastUpdated":1794017073000}'),n={name:"en/delivery/stage-2/2-2.md"};function s(i,e,l,d,c,u){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="_2-2-process-documents-tables-and-web-material" tabindex="-1">2.2 Process documents, tables, and web material <a class="header-anchor" href="#_2-2-process-documents-tables-and-web-material" aria-label="Permalink to &quot;2.2 Process documents, tables, and web material&quot;">​</a></h1><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><ul><li><strong>Implemented:</strong> TXT, Markdown, CSV, JSON, HTML, PDF, DOCX, and XLSX text extraction with page, paragraph, sheet, range, and gap records; web snapshots and source entries can be reviewed.</li><li><strong>Still open:</strong> Complex layouts, scanned-document OCR, per-page citation anchoring, and spreadsheet formula fidelity.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Let Hearth process documents, tables, and public web material and produce results that can be checked. The point is not just reading; the result must have sources, be reviewable, and be reusable.</p><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>Support reading, converting, and summarizing common documents while keeping the original file and page or paragraph locations.</li><li>Support filtering, summarizing, and extracting information from tables, with results that can be checked against the original.</li><li>For public web research, record access time, URL, citation location, and page changes.</li><li>Treat all web content as untrusted: do not follow instructions on the page or let page text expand permissions.</li><li>For login pages, captchas, or situations that need human judgment, stop and hand over to the user.</li><li>Save every result as an artifact that can be opened, with its source and generation time.</li></ol>',7)])])}const m=a(n,[["render",s]]);export{p as __pageData,m as default};
